it('P5: tách đúng cả hai vế của mã ghép kiểu R4.21+R4.27', () => {
    const ma = trichMaLuat('R4.21+R4.27');
    expect(ma.size).toBe(2);
    expect(ma.has('R4.21')).toBe(true);
    expect(ma.has('R4.27')).toBe(true);
  });

it('P6: không bắt nhầm chữ thường / số trần thành mã luật', () => {
    const ma = trichMaLuat('xem mục r1.5 và phụ lục a1, bảng 12.3');
    expect(ma.size).toBe(0);
  });
